#!/bin/sh
# layer-2 load audit -- php -- generated by
# Research/data_representation/audit_generate.py . Do not hand-edit; regenerate.
# Every line of /out/l2_php.txt is FACT_ID|RESULT, FACT_ID being
# <form>.<representation>.<probe>.
set -u
ROOT=/work/l2_php
rm -rf "$ROOT"; mkdir -p "$ROOT"
export HOME=/work
export GOFLAGS=-mod=mod
export GO111MODULE=off
export GOCACHE=/work/.gocache
export GOPATH=/work/.gopath
export PATH=/persist/dart-sdk/bin:$PATH

# swift's binaries want an ncurses name the image does not ship under; the fix
# is per-container, so every script that may touch swift re-applies it.
ncurses_fix() {
  if [ -f /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 ]; then
    ln -sf /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 \
       /usr/lib/x86_64-linux-gnu/libncurses.so.6 2>/dev/null
    ldconfig 2>/dev/null
  fi
}
ncurses_fix

OUT=/out/l2_php.txt
: > "$OUT"
echo "=== layer-2 load audit -- php ==="
date -u +%Y-%m-%dT%H:%M:%SZ
if ! command -v php >/dev/null 2>&1; then
  echo "php: TOOLCHAIN ABSENT -- nothing run"
  echo "__ABSENT__|<absent>" >> "$OUT"
  exit 0
fi


# ---- cell nothing.null (1 probes)
D=$ROOT/nothing_null; mkdir -p "$D"; cd "$D"
cat > main.php <<'L2_SRC_EOF'
<?php

function _p0() {
  $v = null;
  return (var_export($v, true));
}
try {
  echo "nothing.null.null|" . _p0() . "\n";
} catch (Throwable $e) {
  echo "nothing.null.null|<error:" . get_class($e) . ">\n";
}
L2_SRC_EOF
if timeout 60 php main.php > run.out 2> run.err; then :; else
  echo "nothing.null: run ended early ($(grep -c "|" run.out) lines printed)"
  sed -n 1,6p run.err
fi
grep "|" run.out >> "$OUT"
grep -qF "nothing.null.null|" run.out || echo "nothing.null.null|<no-output>" >> "$OUT"

